#!/usr/bin/env node

// ====================================================================
// 動的ワークフロー生成システム
// ====================================================================
// 目的: プロジェクトの要件に基づいて GitHub Actions ワークフローを
//      動的に生成し、標準化された構造とベストプラクティスを保証する
//
// 機能:
//   1. テンプレートベースのワークフロー生成
//   2. 日本語コメントの自動追加
//   3. セキュリティ設定の自動適用
//   4. パフォーマンス最適化の組み込み
// ====================================================================

const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

/**
 * ワークフロー設定クラス
 */
class WorkflowConfig {
  constructor(options) {
    this.name = options.name;
    this.category = options.category;
    this.description = options.description;
    this.triggers = options.triggers || [];
    this.env = options.env || {};
    this.permissions = options.permissions || {};
    this.jobs = options.jobs || [];
  }

  /**
   * カテゴリに応じた絵文字を取得
   */
  getEmoji() {
    const emojiMap = {
      'deploy': '📦',
      'test': '🧪',
      'security': '🔒',
      'monitoring': '📊',
      'automation': '🤖',
      'compliance': '⚖️',
      'notification': '🔔',
      'developer': '🔧',
      'performance': '⚡',
      'quality': '✨'
    };
    return emojiMap[this.category] || '🎯';
  }

  /**
   * 標準化されたワークフロー名を生成
   */
  generateWorkflowName() {
    const emoji = this.getEmoji();
    return `${emoji} ${this.name}`;
  }

  /**
   * ファイル名を生成（番号付き）
   */
  generateFileName() {
    const categoryNumbers = {
      'deploy': '01',
      'test': '02',
      'security': '03',
      'monitoring': '04',
      'automation': '05',
      'compliance': '06',
      'notification': '07',
      'developer': '08',
      'performance': '09',
      'quality': '10'
    };
    const number = categoryNumbers[this.category] || '99';
    const sanitizedName = this.name.toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    return `${number}-${this.category}-${sanitizedName}.yml`;
  }
}

/**
 * ワークフロー生成器クラス
 */
class WorkflowGenerator {
  constructor() {
    this.templates = this.loadTemplates();
  }

  /**
   * テンプレートを読み込む
   */
  loadTemplates() {
    const templatePath = path.join(__dirname, 'templates');
    const templates = {};
    
    if (fs.existsSync(templatePath)) {
      const files = fs.readdirSync(templatePath);
      files.forEach(file => {
        if (file.endsWith('.yml')) {
          const name = path.basename(file, '.yml');
          const content = fs.readFileSync(path.join(templatePath, file), 'utf8');
          templates[name] = yaml.load(content);
        }
      });
    }
    
    return templates;
  }

  /**
   * ヘッダーコメントを生成
   */
  generateHeader(config) {
    const now = new Date().toISOString().split('T')[0];
    return `# ====================================================================
# ${config.generateWorkflowName()} - ${config.description}
# ====================================================================
# 目的: ${config.description}
# 
# 実行タイミング:
${config.triggers.map(t => `#   - ${t.description}`).join('\n')}
#
# 主な処理:
${config.jobs.map((j, i) => `#   ${i + 1}. ${j.description}`).join('\n')}
#
# 依存関係: ${config.jobs.map(j => j.name).join(' → ')}
# 実行時間目安: 約${this.estimateExecutionTime(config)}分
# リソース使用量: ${this.estimateResourceUsage(config)}
# チーム責任者: ${this.getResponsibleTeam(config.category)}
# 
# Version: 1.0.0
# Last Updated: ${now}
# Generated by: Workflow Generator v2.0
# ====================================================================`;
  }

  /**
   * 実行時間を推定
   */
  estimateExecutionTime(config) {
    const baseTime = {
      'deploy': 15,
      'test': 10,
      'security': 20,
      'monitoring': 5,
      'automation': 10,
      'compliance': 15,
      'notification': 2,
      'developer': 8,
      'performance': 12,
      'quality': 10
    };
    return baseTime[config.category] || 10;
  }

  /**
   * リソース使用量を推定
   */
  estimateResourceUsage(config) {
    const resourceMap = {
      'deploy': '中（CPU 2コア、メモリ 4GB）',
      'test': '高（CPU 4コア、メモリ 8GB）',
      'security': '中（CPU 2コア、メモリ 4GB）',
      'monitoring': '低（CPU 1コア、メモリ 2GB）',
      'automation': '低（CPU 1コア、メモリ 2GB）',
      'compliance': '中（CPU 2コア、メモリ 4GB）',
      'notification': '低（CPU 1コア、メモリ 1GB）',
      'developer': '中（CPU 2コア、メモリ 4GB）',
      'performance': '高（CPU 4コア、メモリ 8GB）',
      'quality': '中（CPU 2コア、メモリ 4GB）'
    };
    return resourceMap[config.category] || '中（CPU 2コア、メモリ 4GB）';
  }

  /**
   * 責任チームを取得
   */
  getResponsibleTeam(category) {
    const teamMap = {
      'deploy': 'DevOpsエンジニア',
      'test': 'QAエンジニア',
      'security': 'セキュリティエンジニア',
      'monitoring': 'SREエンジニア',
      'automation': 'DevOpsエンジニア',
      'compliance': 'コンプライアンスチーム',
      'notification': 'プロジェクトマネージャー',
      'developer': 'リードエンジニア',
      'performance': 'パフォーマンスエンジニア',
      'quality': 'QAエンジニア'
    };
    return teamMap[category] || 'DevOpsエンジニア';
  }

  /**
   * 権限設定を生成
   */
  generatePermissions(permissions) {
    const defaultPermissions = {
      'contents': 'read',
      'pull-requests': 'write',
      'checks': 'write'
    };
    
    const merged = { ...defaultPermissions, ...permissions };
    
    return `# 権限設定 - 最小権限の原則
permissions:${Object.entries(merged).map(([key, value]) => {
      const descriptions = {
        'contents': 'リポジトリコンテンツの' + (value === 'write' ? '書き込み' : '読み取り'),
        'pull-requests': 'PRコメントの書き込み',
        'checks': 'チェック結果の書き込み',
        'security-events': 'セキュリティイベントの書き込み',
        'packages': 'パッケージの' + (value === 'write' ? '公開' : '読み取り'),
        'actions': 'アクションログの読み取り',
        'pages': 'GitHub Pagesの' + (value === 'write' ? '更新' : '読み取り')
      };
      const padding = ' '.repeat(Math.max(0, 22 - key.length));
      return `\n  ${key}: ${value}${padding}# ${descriptions[key] || key}`;
    }).join('')}`;
  }

  /**
   * 環境変数設定を生成
   */
  generateEnv(env) {
    const standardEnv = {
      'NODE_VERSION': "'18'",
      'CACHE_VERSION': "'v2'",
      'TIMEOUT_MINUTES': '30',
      'RETRY_COUNT': '3'
    };
    
    const merged = { ...standardEnv, ...env };
    
    return `# 環境変数の標準定義
env:${Object.entries(merged).map(([key, value]) => {
      const descriptions = {
        'NODE_VERSION': 'Node.jsバージョン統一',
        'CACHE_VERSION': 'キャッシュバージョン管理',
        'TIMEOUT_MINUTES': 'デフォルトタイムアウト',
        'RETRY_COUNT': 'リトライ回数'
      };
      const padding = ' '.repeat(Math.max(0, 30 - key.length - value.toString().length));
      return `\n  ${key}: ${value}${padding}# ${descriptions[key] || ''}`;
    }).join('')}`;
  }

  /**
   * ワークフローを生成
   */
  generate(config) {
    const workflowConfig = new WorkflowConfig(config);
    
    const workflow = {
      name: workflowConfig.generateWorkflowName(),
      on: this.generateTriggers(workflowConfig.triggers),
      permissions: yaml.load(this.generatePermissions(workflowConfig.permissions)),
      concurrency: {
        group: '${{ github.workflow }}-${{ github.ref }}',
        'cancel-in-progress': '${{ github.ref != \'refs/heads/main\' }}'
      },
      env: yaml.load(this.generateEnv(workflowConfig.env)),
      jobs: this.generateJobs(workflowConfig.jobs)
    };

    const header = this.generateHeader(workflowConfig);
    const yamlContent = yaml.dump(workflow, {
      indent: 2,
      lineWidth: -1,
      noRefs: true,
      sortKeys: false
    });

    return header + '\n\n' + yamlContent;
  }

  /**
   * トリガー設定を生成
   */
  generateTriggers(triggers) {
    const on = {};
    
    triggers.forEach(trigger => {
      switch (trigger.type) {
        case 'push':
          on.push = { branches: trigger.branches || ['main', 'develop'] };
          break;
        case 'pull_request':
          on.pull_request = { branches: trigger.branches || ['main'] };
          break;
        case 'schedule':
          on.schedule = [{ cron: trigger.cron }];
          break;
        case 'workflow_dispatch':
          on.workflow_dispatch = trigger.inputs || null;
          break;
      }
    });
    
    return on;
  }

  /**
   * ジョブを生成
   */
  generateJobs(jobConfigs) {
    const jobs = {};
    
    jobConfigs.forEach((jobConfig, index) => {
      const jobName = jobConfig.id || `job-${index + 1}`;
      
      jobs[jobName] = {
        name: `${this.getJobEmoji(jobConfig.type)} ${jobConfig.name}`,
        'runs-on': jobConfig.runsOn || 'ubuntu-latest',
        'timeout-minutes': jobConfig.timeout || 30,
        needs: jobConfig.needs || (index > 0 ? [jobConfigs[index - 1].id] : undefined),
        steps: this.generateSteps(jobConfig.steps)
      };
      
      // ジョブレベルコメントを追加
      const comment = `    # 🎯 目的: ${jobConfig.description}
    # ⏱️ 推定時間: ${jobConfig.estimatedTime || '5-10'}分
    # 🔧 主要処理: ${jobConfig.mainProcess || '処理内容'}
    # 📋 成果物: ${jobConfig.artifacts || 'なし'}
    # ⚠️ 注意点: ${jobConfig.notes || 'なし'}`;
      
      // コメントをジョブ定義に組み込む（YAML文字列として）
      jobs[`__comment_${jobName}`] = comment;
    });
    
    return jobs;
  }

  /**
   * ジョブタイプに応じた絵文字を取得
   */
  getJobEmoji(type) {
    const emojiMap = {
      'setup': '🔧',
      'build': '🏗️',
      'test': '🧪',
      'deploy': '🚀',
      'notify': '📢',
      'cleanup': '🧹',
      'analysis': '📊',
      'security': '🔐'
    };
    return emojiMap[type] || '⚙️';
  }

  /**
   * ステップを生成
   */
  generateSteps(stepConfigs) {
    return stepConfigs.map(step => {
      const stepDef = {
        name: step.name
      };
      
      if (step.uses) {
        stepDef.uses = step.uses;
        if (step.with) {
          stepDef.with = step.with;
        }
      } else if (step.run) {
        stepDef.run = step.run;
        if (step.env) {
          stepDef.env = step.env;
        }
      }
      
      if (step.id) {
        stepDef.id = step.id;
      }
      
      if (step.if) {
        stepDef.if = step.if;
      }
      
      return stepDef;
    });
  }

  /**
   * ワークフローをファイルに保存
   */
  save(config, outputDir = '.github/workflows') {
    const workflowConfig = new WorkflowConfig(config);
    const content = this.generate(config);
    const fileName = workflowConfig.generateFileName();
    const filePath = path.join(outputDir, fileName);
    
    // ディレクトリが存在しない場合は作成
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }
    
    fs.writeFileSync(filePath, content, 'utf8');
    console.log(`✅ ワークフロー生成完了: ${filePath}`);
    
    return filePath;
  }
}

// CLI実行
if (require.main === module) {
  const generator = new WorkflowGenerator();
  
  // サンプル設定
  const sampleConfig = {
    name: 'サンプルワークフロー',
    category: 'test',
    description: '動的生成システムのテストワークフロー',
    triggers: [
      { type: 'push', branches: ['main'], description: 'mainブランチへのプッシュ時' },
      { type: 'workflow_dispatch', description: '手動実行' }
    ],
    jobs: [
      {
        id: 'setup',
        name: '環境セットアップ',
        type: 'setup',
        description: 'テスト環境の準備',
        steps: [
          {
            name: 'リポジトリコードの取得',
            uses: 'actions/checkout@v4'
          },
          {
            name: 'Node.js環境のセットアップ',
            uses: 'actions/setup-node@v4',
            with: {
              'node-version': '${{ env.NODE_VERSION }}',
              'cache': 'npm'
            }
          }
        ]
      },
      {
        id: 'test',
        name: 'テスト実行',
        type: 'test',
        description: 'ユニットテストとカバレッジ計測',
        needs: ['setup'],
        steps: [
          {
            name: 'テストの実行',
            run: 'npm test'
          }
        ]
      }
    ]
  };
  
  // ワークフロー生成
  const output = generator.generate(sampleConfig);
  console.log(output);
}

module.exports = { WorkflowGenerator, WorkflowConfig };